    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    anchors_by_col = [[] for _ in range(w)]

    # A one-cell hole inside a horizontal run is an anchor of that run's color.
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            color = row[c - 1]
            if color != 0 and row[c] == 0 and row[c + 1] == color:
                out[r][c] = color
                anchors_by_col[c].append((r, color))

    # Existing colored cells (including vertical guide lines) are anchors too.
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                anchors_by_col[c].append((r, color))

    # For each column, extend the upper anchor to the top, and fill each
    # interval between anchors with the color of the lower anchor.
    for c, anchors in enumerate(anchors_by_col):
        if not anchors:
            continue
        anchors = sorted(set(anchors))
        first_r, first_color = anchors[0]
        for rr in range(first_r):
            out[rr][c] = first_color
        for (upper_r, _), (lower_r, lower_color) in zip(anchors, anchors[1:]):
            for rr in range(upper_r + 1, lower_r):
